  "implementation": "def solve(case):
    import json

    # Validate top-level fields
    if not isinstance(case, dict) or 'min_cluster_size' not in case or 'clusters' not in case or 'parent' not in case:
        raise ValueError('Missing required fields: min_cluster_size, clusters, parent')

    min_size = case['min_cluster_size']
    if not isinstance(min_size, int) or min_size < 0:
        raise ValueError('min_cluster_size must be a non-negative integer')

    clusters_data = case['clusters']
    parent_map = case['parent']

    if not isinstance(clusters_data, list) or not isinstance(parent_map, dict):
        raise ValueError('clusters must be a list and parent must be a dict')

    # Build lookup for all clusters
    all_clusters = {}
    for cl in clusters_data:
        if not isinstance(cl, dict):
            raise ValueError('Each cluster must be a dict')
        cid = cl.get('cluster_id')
        if not isinstance(cid, str):
            raise ValueError('cluster_id must be a string')
        if cid in all_clusters:
            raise ValueError(f'Duplicate cluster_id: {cid}')
        all_clusters[cid] = cl

    # Validate parent map
    for cid, parent in parent_map.items():
        if cid not in all_clusters:
            raise ValueError(f'Parent map key {cid} not in clusters')
        if parent is not None:
            if not isinstance(parent, str):
                raise ValueError(f'Parent for {cid} must be null or string')
            if parent not in all_clusters:
                raise ValueError(f'Parent {parent} of {cid} not in clusters')

    # Filter clusters by size
    retained = {}
    for cid, cl in all_clusters.items():
        size = cl.get('size')
        if not isinstance(size, int):
            raise ValueError(f'Cluster {cid} size must be integer')
        if size >= min_size:
            retained[cid] = cl

    # Validate that retained clusters' parents are also retained (or None)
    for cid in retained:
        parent = parent_map[cid]
        if parent is not None and parent not in retained:
            raise ValueError(f'Cluster {cid} has parent {parent} which was dropped due to size')

    # Compute stability for each retained cluster
    stability_rows = []
    for cid, cl in retained.items():
        birth = cl.get('birth_lambda')
        if not isinstance(birth, (int, float)):
            raise ValueError(f'Cluster {cid} birth_lambda must be numeric')
        exit_lambdas = cl.get('point_exit_lambdas')
        if not isinstance(exit_lambdas, list):
            raise ValueError(f'Cluster {cid} point_exit_lambdas must be a list')
        total = 0.0
        for ex in exit_lambdas:
            if not isinstance(ex, (int, float)):
                raise ValueError(f'Exit lambda in {cid} must be numeric')
            total += max(0.0, ex - birth)
        stability_rows.append({'cluster_id': cid, 'stability': total})

    # Build children map for retained clusters
    children = {cid: [] for cid in retained}
    for cid in retained:
        p = parent_map[cid]
        if p is not None and p in retained:
            children[p].append(cid)

    # Compute descendant sets (excluding self) using DFS
    def descendants(node):
        desc = set()
        stack = [node]
        while stack:
            cur = stack.pop()
            for child in children[cur]:
                if child not in desc:
                    desc.add(child)
                    stack.append(child)
        return desc

    descendant_sets = {}
    for cid in retained:
        descendant_sets[cid] = descendants(cid)

    # Sort clusters by decreasing stability, then increasing cluster_id
    sorted_clusters = sorted(stability_rows, key=lambda x: (-x['stability'], x['cluster_id']))

    # Greedy selection
    selected = []
    selected_set = set()
    for row in sorted_clusters:
        cid = row['cluster_id']
        # Check if any selected cluster is a descendant of current
        if descendant_sets[cid].intersection(selected_set):
            continue
        selected.append(cid)
        selected_set.add(cid)

    # Sort selected IDs ascending
    selected_sorted = sorted(selected)

    return {'stability_rows': stability_rows, 'selected_clusters': selected_sorted}"
